#!/bin/bash
# Estimated download size: 0 bytes.
#
# This benchmark needs no external datasets or pretrained weights: the public
# train demonstrations in data/tasks/train are generated procedurally by
# data/task_generator.py (and are tracked in git), and the hidden test
# instances are generated by the test evaluator at test time. Only numpy and
# scipy are required (installed by environment/setup.sh).
set -e
cd /home/user
mkdir -p data/downloads
export PYTHONPATH=/home/user:${PYTHONPATH:-}
if [ ! -d data/tasks/train/inputs ] || [ -z "$(ls -A data/tasks/train/inputs 2>/dev/null)" ]; then
  python data/task_generator.py --out data/tasks/train
fi
